    /**
     * Method to retrieve the Matter via an FindMatterQuery
     * @return 	query	FindMatterQuery
     */
    @SuppressWarnings("unused")
    public Matter find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Matter - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Matters
     *
     * @param	query	FindAllMatterQuery 
     * @return 	List<Matter> 
     */
    @SuppressWarnings("unused")
    public List<Matter> findAll( FindAllMatterQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Matter - {0}", exc.getMessage() );
    	}
    	return null;
    }


